import{_ as e,o as t,c as a,ac as p}from"./chunks/framework.B-3EzaJq.js";const m=JSON.parse('{"title":"十一届七中全会发表公报 我党第十二次全国代表大会九月一日召开","description":"","frontmatter":{"prev":{"text":"十一届七中全会简介","link":"./"},"next":{"text":"党的十一届七中全会给刘伯承同志的致敬信","link":"./党的十一届七中全会给刘伯承同志的致敬信"}},"headers":[],"relativePath":"11/7/十一届七中全会发表公报 我党第十二次全国代表大会九月一日召开.md","filePath":"11/7/十一届七中全会发表公报 我党第十二次全国代表大会九月一日召开.md"}'),o={name:"11/7/十一届七中全会发表公报 我党第十二次全国代表大会九月一日召开.md"};function r(n,_,s,c,i,l){return t(),a("div",null,[..._[0]||(_[0]=[p('<h1 id="十一届七中全会发表公报-我党第十二次全国代表大会九月一日召开" tabindex="-1">十一届七中全会发表公报 我党第十二次全国代表大会九月一日召开 <a class="header-anchor" href="#十一届七中全会发表公报-我党第十二次全国代表大会九月一日召开" aria-label="Permalink to &quot;十一届七中全会发表公报 我党第十二次全国代表大会九月一日召开&quot;">​</a></h1><p><em>（1982年8月27日）</em></p><blockquote><p>  全会审议并通过了中央委员会向十二大的报告；审议并通过了《中国共产党章程（修改草案）》，一致决定将这两个文件提交十二大审议</p><p>  通过给刘伯承同志蔡畅同志的致敬信，以全会的名义表达全党同志对他们的亲切问候和崇高敬意</p><p>  胡耀邦、叶剑英、邓小平、赵紫阳、李先念、陈云、华国锋同志主持这次会议</p></blockquote><p>  <strong>新华社北京8月6日电</strong> 中国共产党第十一届中央委员会第七次全体会议公报</p><p>  中国共产党第十一届中央委员会第七次全体会议，1982年8月6日在北京举行。</p><p>  全会决定，今年9月1日召开中国共产党第十二次全国代表大会。全会审议并通过了中央委员会向党的第十二次全国代表大会的报告；审议并通过了《中国共产党章程（修改草案）》，一致决定将这两个文件提交党的第十二次全国代表大会审议。</p><p>  全会还讨论并通过了分别给刘伯承同志、蔡畅同志的致敬信。刘伯承同志、蔡畅同志是我们党老一辈的无产阶级革命家，他们在长期的革命和建设事业中对党和人民作出了巨大贡献，七中全会决定在他们因年高久病，不再担任领导职务之际，以全会的名义表达全党同志对他们的亲切问候和崇高敬意。</p><p>  全会正式会议前开了六天的预备会议，就上述议题进行了充分的酝酿和认真的讨论。</p><p>  出席这次会议的，有中央委员一百八十五人，候补中央委员一百一十二人，列席的二十一人。中央政治局常委胡耀邦同志、叶剑英同志、邓小平同志、赵紫阳同志、李先念同志、陈云同志、华国锋同志，主持了这次会议</p>',9)])])}const f=e(o,[["render",r]]);export{m as __pageData,f as default};
